1	/**
2	 * T2.7 result ingestion.
3	 *
4	 * A terminal call becomes rows in one PostgreSQL transaction. PostgREST cannot
5	 * hold that transaction, so this module validates the extraction, forwards it
6	 * to `public.ingest_call_result`, and records the `ingested` timeline row.
7	 * A null or invalid result still writes the transcript and a disposition, so
8	 * the user never learns that extraction failed.
9	 *
10	 * A `slot_change_requested` is a proposal only. This module returns it and
11	 * never writes `slots`.
12	 */
13	
14	import { recordCallEvent } from "./events.ts";
15	import { loadCallFixtures, type TranscriptTurnFixture } from "./fixtures.ts";
16	import { parseStructuredResult } from "./result.ts";
17	
18	export type TerminalCallSource = {
19	  callRunId: string;
20	  userId: string;
21	  raw: unknown;
22	  transcriptTurns: TranscriptTurnFixture[];
23	  structuredResult: unknown | null;
24	};
25	
26	export type IngestCounts = {
27	  items: number;
28	  mentions: number;
29	  retirements: number;
30	  commitments: number;
31	};
32	
33	export type IngestResult = {
34	  alreadyIngested: boolean;
35	  disposition: string;
36	  counts: IngestCounts;
37	  slotChangeRequested: string | null;
38	};
39	
40	export type IngestDeps = {
41	  apiUrl: string;
42	  serviceRoleKey: string;
43	  fetch: typeof fetch;
44	};
45	
46	type TerminalState = "completed" | "failed" | "canceled";
47	type Disposition = "answered_extracted" | "answered_no_result" | "not_answered" | "canceled";
48	
49	type IngestSummary = {
50	  already_ingested: boolean;
51	  disposition: string;
52	  counts: IngestCounts;
53	  slot_change_requested: string | null;
54	};
55	
56	function requireString(value: unknown, message: string): string {
57	  if (typeof value !== "string" || value.trim() === "") throw new Error(message);
58	  return value;
59	}
60	
61	function requireObject(value: unknown, message: string): Record<string, unknown> {
62	  if (value === null || Array.isArray(value) || typeof value !== "object") {
63	    throw new Error(message);
64	  }
65	  return value as Record<string, unknown>;
66	}
67	
68	function requireBoolean(value: unknown, message: string): boolean {
69	  if (typeof value !== "boolean") throw new Error(message);
70	  return value;
71	}
72	
73	function requireCount(value: unknown, message: string): number {
74	  if (typeof value !== "number" || !Number.isInteger(value) || value < 0) {
75	    throw new Error(message);
76	  }
77	  return value;
78	}
79	
80	function requireTurns(value: unknown): TranscriptTurnFixture[] {
81	  if (!Array.isArray(value)) throw new Error("ingest requires transcript turns");
82	  return value.map((turn, index) => {
83	    const record = requireObject(turn, `transcript turn ${index} must be an object`);
84	    const offset = record.offset_seconds;
85	    if (typeof offset !== "number" || !Number.isInteger(offset)) {
86	      throw new Error(`transcript turn ${index} requires an integer offset`);
87	    }
88	    return {
89	      offset_seconds: offset,
90	      speaker: requireString(record.speaker, `transcript turn ${index} requires a speaker`),
91	      text: requireString(record.text, `transcript turn ${index} requires text`),
92	    };
93	  });
94	}
95	
96	function terminalState(raw: Record<string, unknown>): TerminalState {
97	  const status = raw.status;
98	  if (status === "completed" || status === "failed" || status === "canceled") return status;
99	  throw new Error("ingest requires a terminal call status");
100	}
101	
102	function dispositionFor(state: TerminalState, valid: boolean): Disposition {
103	  if (state === "canceled") return "canceled";
104	  if (state === "failed") return "not_answered";
105	  return valid ? "answered_extracted" : "answered_no_result";
106	}
107	
108	function apiBase(apiUrl: string): string {
109	  const base = apiUrl.replace(/\/+$/, "");
110	  if (base.includes("supabase.co")) throw new Error("must use ORMA_API_URL, not project host");
111	  return base;
112	}
113	
114	function readSummary(value: unknown): IngestSummary {
115	  const record = requireObject(value, "ingest returned no summary");
116	  const counts = requireObject(record.counts, "ingest summary requires counts");
117	  return {
118	    already_ingested: requireBoolean(record.already_ingested, "ingest summary requires an already_ingested flag"),
119	    disposition: requireString(record.disposition, "ingest summary requires a disposition"),
120	    counts: {
121	      items: requireCount(counts.items, "ingest summary requires an item count"),
122	      mentions: requireCount(counts.mentions, "ingest summary requires a mention count"),
123	      retirements: requireCount(counts.retirements, "ingest summary requires a retirement count"),
124	      commitments: requireCount(counts.commitments, "ingest summary requires a commitment count"),
125	    },
126	    slot_change_requested: typeof record.slot_change_requested === "string"
127	      ? record.slot_change_requested
128	      : null,
129	  };
130	}
131	
132	export function depsFromEnv(
133	  getEnv: (name: string) => string | undefined = (name) => Deno.env.get(name),
134	  fetchImpl: typeof fetch = fetch,
135	): IngestDeps {
136	  const apiUrl = getEnv("ORMA_API_URL");
137	  const serviceRoleKey = getEnv("SUPABASE_SERVICE_ROLE_KEY");
138	  if (!apiUrl) throw new Error("missing ORMA_API_URL");
139	  if (!serviceRoleKey) throw new Error("missing SUPABASE_SERVICE_ROLE_KEY");
140	  return { apiUrl, serviceRoleKey, fetch: fetchImpl };
141	}
142	
143	/**
144	 * Ingests one terminal call. The caller supplies the authoritative payload
145	 * plus the transcript turns and structured result it extracted from that
146	 * payload, so this module never dials CALL-E. Environment is reached only
147	 * through `ORMA_API_URL`.
148	 */
149	export async function ingestTerminalRun(
150	  source: TerminalCallSource,
151	  deps: IngestDeps,
152	): Promise<IngestResult> {
153	  const input = requireObject(source, "ingest requires a terminal call source");
154	  const runId = requireString(input.callRunId, "ingest requires a call run id");
155	  const userId = requireString(input.userId, "ingest requires a user id");
156	  const raw = requireObject(input.raw, "ingest requires a terminal call payload");
157	  const turns = requireTurns(input.transcriptTurns);
158	  const state = terminalState(raw);
159	  const parsed = parseStructuredResult(input.structuredResult ?? null);
160	  const valid = parsed.result !== null;
161	  const disposition = dispositionFor(state, valid);
162	
163	  const completedAt = typeof raw.completed_at === "string" && raw.completed_at.trim() !== ""
164	    ? raw.completed_at
165	    : null;
166	  const calleCallId = typeof raw.id === "string" && raw.id.trim() !== "" ? raw.id : null;
167	
168	  const response = await deps.fetch(`${apiBase(deps.apiUrl)}/rest/v1/rpc/ingest_call_result`, {
169	    method: "POST",
170	    headers: {
171	      apikey: deps.serviceRoleKey,
172	      authorization: `Bearer ${deps.serviceRoleKey}`,
173	      "content-type": "application/json",
174	    },
175	    body: JSON.stringify({
176	      p_call_run_id: runId,
177	      p_user_id: userId,
178	      p_transcript_turns: turns,
179	      p_raw: raw,
180	      p_structured: parsed.result,
181	      p_result_valid: valid,
182	      p_result_error: parsed.reason,
183	      p_state: state,
184	      p_disposition: disposition,
185	      p_mood: parsed.result?.mood ?? null,
186	      p_completed_at: completedAt,
187	    }),
188	  });
189	  if (!response.ok) throw new Error("call result ingestion failed");
190	
191	  const summary = readSummary(await response.json());
192	
193	  if (!summary.already_ingested) {
194	    await recordCallEvent(runId, "ingested", {
195	      call_run_id: runId,
196	      calle_call_id: calleCallId,
197	      state,
198	      disposition: summary.disposition,
199	      item_count: summary.counts.items,
200	      mention_count: summary.counts.mentions,
201	      retirement_count: summary.counts.retirements,
202	      commitment_count: summary.counts.commitments,
203	    }, deps);
204	  }
205	
206	  return {
207	    alreadyIngested: summary.already_ingested,
208	    disposition: summary.disposition,
209	    counts: summary.counts,
210	    slotChangeRequested: summary.slot_change_requested,
211	  };
212	}
213	
214	const testFn =
215	  (Deno as { test?: (name: string, fn: () => void | Promise<void>) => void })
216	    .test;
217	
218	if (typeof testFn === "function") {
219	  const baseUrl = "https://orma-api.nryn.dev";
220	  const runId = "11111111-1111-4111-8111-111111111111";
221	  const userId = "33333333-3333-4333-8333-333333333333";
222	  const itemId = "22222222-2222-4222-8222-222222222222";
223	  const zeroCounts: IngestCounts = { items: 0, mentions: 0, retirements: 0, commitments: 0 };
224	
225	  const deps = (fetchImpl: typeof fetch): IngestDeps => ({
226	    apiUrl: baseUrl,
227	    serviceRoleKey: "service-key",
228	    fetch: fetchImpl,
229	  });
230	
231	  type MockState = {
232	    rpcBodies: Record<string, unknown>[];
233	    events: Record<string, unknown>[];
234	    summary: () => IngestSummary;
235	  };
236	
237	  // Every mock branches on URL and method. Anything else throws, so a stray
238	  // request fails the test instead of passing silently.
239	  const mock = (state: MockState): typeof fetch =>
240	  (input, init) => {
241	    const request = new Request(input, init);
242	    const { pathname } = new URL(request.url);
243	    if (pathname === "/rest/v1/rpc/ingest_call_result") {
244	      if (request.method !== "POST") throw new Error(`unexpected ${request.method} ${request.url}`);
245	      return request.json().then((body) => {
246	        state.rpcBodies.push(body as Record<string, unknown>);
247	        return Response.json(state.summary());
248	      });
249	    }
250	    if (pathname === "/rest/v1/call_events") {
251	      if (request.method !== "POST") throw new Error(`unexpected ${request.method} ${request.url}`);
252	      return request.json().then((row) => {
253	        state.events.push(row as Record<string, unknown>);
254	        return new Response(null, { status: 201 });
255	      });
256	    }
257	    throw new Error(`unexpected request ${request.method} ${request.url}`);
258	  };
259	
260	  testFn("the completed fixture produces items, mentions, retirements and commitments", async () => {
261	    const { completed } = await loadCallFixtures();
262	    const attempt = completed.recipients[0].attempts[0];
263	    // The recorded call retired nothing and promised nothing. This test adds
264	    // one of each so those branches still run against the recorded payload.
265	    const structuredResult = {
266	      ...(completed.structured_result as Record<string, unknown>),
267	      retired_items: [{ item_id: itemId, evidence_offset_seconds: 62 }],
268	      commitments: [{ item_id: itemId, due: "2026-09-12T03:00:00.000Z", evidence_offset_seconds: 80 }],
269	    };
270	    const state: MockState = {
271	      rpcBodies: [],
272	      events: [],
273	      summary: () => ({
274	        already_ingested: false,
275	        disposition: "answered_extracted",
276	        counts: { items: 1, mentions: 3, retirements: 1, commitments: 1 },
277	        slot_change_requested: "no",
278	      }),
279	    };
280	
281	    const result = await ingestTerminalRun({
282	      callRunId: runId,
283	      userId,
284	      raw: completed,
285	      transcriptTurns: attempt.transcript_turns,
286	      structuredResult,
287	    }, deps(mock(state)));
288	
289	    if (state.rpcBodies.length !== 1) throw new Error("the completed fixture must ingest through one RPC");
290	    const body = state.rpcBodies[0];
291	    if (body.p_call_run_id !== runId || body.p_user_id !== userId) {
292	      throw new Error("the RPC lost the run or the user");
293	    }
294	    if (body.p_state !== "completed" || body.p_disposition !== "answered_extracted") {
295	      throw new Error("the completed call did not become an answered extraction");
296	    }
297	    if (body.p_result_valid !== true || body.p_result_error !== null || body.p_mood !== "unknown") {
298	      throw new Error("the valid result was not forwarded intact");
299	    }
300	    if (JSON.stringify(body.p_raw) !== JSON.stringify(completed)) {
301	      throw new Error("the raw provider payload was not preserved");
302	    }
303	    if (JSON.stringify(body.p_transcript_turns) !== JSON.stringify(attempt.transcript_turns)) {
304	      throw new Error("the transcript turns were not preserved");
305	    }
306	    const structured = body.p_structured as Record<string, unknown>;
307	    if (JSON.stringify(structured.captured_items) !== JSON.stringify([{ text: "Continental", evidence_offset_seconds: 44 }])) {
308	      throw new Error("the captured item did not survive extraction");
309	    }
310	    const retired = structured.retired_items as Record<string, unknown>[];
311	    const commitments = structured.commitments as Record<string, unknown>[];
312	    if (retired[0]?.evidence_offset_seconds !== 62 || commitments[0]?.due !== "2026-09-12T03:00:00.000Z") {
313	      throw new Error("the retirement or commitment lost its evidence");
314	    }
315	
316	    if (result.alreadyIngested !== false || result.disposition !== "answered_extracted") {
317	      throw new Error("the RPC summary was not surfaced");
318	    }
319	    if (result.counts.items !== 1 || result.counts.mentions !== 3 || result.counts.retirements !== 1 || result.counts.commitments !== 1) {
320	      throw new Error("the RPC counts were not surfaced");
321	    }
322	    if (result.slotChangeRequested !== "no") throw new Error("the slot proposal was not surfaced");
323	
324	    if (state.events.length !== 1) throw new Error("ingest must record exactly one timeline row");
325	    const event = state.events[0];
326	    if (event.kind !== "ingested" || event.call_run_id !== runId) {
327	      throw new Error("the timeline row lost its run or its kind");
328	    }
329	    const detail = event.detail as Record<string, unknown>;
330	    if (detail.state !== "completed" || detail.calle_call_id !== completed.id) {
331	      throw new Error("the timeline row must name the call and its state");
332	    }
333	    if (detail.item_count !== 1 || detail.mention_count !== 3 || detail.retirement_count !== 1 || detail.commitment_count !== 1) {
334	      throw new Error("the timeline row must carry the counts");
335	    }
336	  });
337	
338	  testFn("the invalid fixture writes a transcript and a disposition with no partial state", async () => {
339	    const raw = await Deno.readTextFile(
340	      new URL("../../../testdata/calle/webhook-result-validation-failed.documented.json", import.meta.url),
341	    );
342	    const fixture = JSON.parse(raw) as { body: { id: string; data: { id: string } } };
343	    const state: MockState = {
344	      rpcBodies: [],
345	      events: [],
346	      summary: () => ({
347	        already_ingested: false,
348	        disposition: "answered_no_result",
349	        counts: zeroCounts,
350	        slot_change_requested: null,
351	      }),
352	    };
353	
354	    const result = await ingestTerminalRun({
355	      callRunId: runId,
356	      userId,
357	      raw: {
358	        id: fixture.body.data.id,
359	        status: "completed",
360	        structured_result: null,
361	        completed_at: "2026-09-13T12:00:30.000Z",
362	      },
363	      transcriptTurns: [],
364	      structuredResult: fixture.body,
365	    }, deps(mock(state)));
366	
367	    if (state.rpcBodies.length !== 1) throw new Error("the invalid fixture must still reach the RPC");
368	    const body = state.rpcBodies[0];
369	    if (body.p_structured !== null || body.p_result_valid !== false) {
370	      throw new Error("an invalid result must not be persisted as structured");
371	    }
372	    if (typeof body.p_result_error !== "string" || body.p_result_error.length === 0) {
373	      throw new Error("an invalid result must carry its failure reason");
374	    }
375	    if (body.p_disposition !== "answered_no_result" || body.p_state !== "completed") {
376	      throw new Error("an answered call with no result must be answered_no_result");
377	    }
378	    if (JSON.stringify(body.p_transcript_turns) !== "[]") {
379	      throw new Error("the transcript must still be written on an invalid result");
380	    }
381	    if (result.disposition !== "answered_no_result" || result.counts.items !== 0 || result.counts.mentions !== 0) {
382	      throw new Error("an invalid result must leave no partial state");
383	    }
384	    if (state.events.length !== 1 || (state.events[0].detail as Record<string, unknown>).disposition !== "answered_no_result") {
385	      throw new Error("the timeline must record the answered_no_result disposition");
386	    }
387	  });
388	
389	  testFn("a retirement without an evidence offset is rejected", async () => {
390	    const state: MockState = {
391	      rpcBodies: [],
392	      events: [],
393	      summary: () => ({
394	        already_ingested: false,
395	        disposition: "answered_no_result",
396	        counts: zeroCounts,
397	        slot_change_requested: null,
398	      }),
399	    };
400	
401	    const result = await ingestTerminalRun({
402	      callRunId: runId,
403	      userId,
404	      raw: { id: "call_unoffset_retirement", status: "completed" },
405	      transcriptTurns: [],
406	      structuredResult: { captured_items: [], retired_items: [{ item_id: itemId }] },
407	    }, deps(mock(state)));
408	
409	    if (state.rpcBodies.length !== 1) throw new Error("the rejected result must reach the RPC as invalid");
410	    const body = state.rpcBodies[0];
411	    if (body.p_structured !== null || body.p_result_valid !== false) {
412	      throw new Error("a retirement without an evidence offset must be rejected, never written");
413	    }
414	    if (typeof body.p_result_error !== "string" || body.p_result_error.length === 0) {
415	      throw new Error("the rejected retirement must carry a reason");
416	    }
417	    if (result.disposition !== "answered_no_result") {
418	      throw new Error("a rejected extraction must fall back to answered_no_result");
419	    }
420	  });
421	
422	  testFn("re-ingesting the same run twice changes nothing", async () => {
423	    const { completed } = await loadCallFixtures();
424	    const attempt = completed.recipients[0].attempts[0];
425	    let ingests = 0;
426	    const state: MockState = {
427	      rpcBodies: [],
428	      events: [],
429	      summary: () => ingests++ === 0
430	        ? {
431	          already_ingested: false,
432	          disposition: "answered_extracted",
433	          counts: { items: 1, mentions: 1, retirements: 0, commitments: 0 },
434	          slot_change_requested: "no",
435	        }
436	        : {
437	          already_ingested: true,
438	          disposition: "answered_extracted",
439	          counts: zeroCounts,
440	          slot_change_requested: "no",
441	        },
442	    };
443	    const source: TerminalCallSource = {
444	      callRunId: runId,
445	      userId,
446	      raw: completed,
447	      transcriptTurns: attempt.transcript_turns,
448	      structuredResult: completed.structured_result,
449	    };
450	
451	    const first = await ingestTerminalRun(source, deps(mock(state)));
452	    const second = await ingestTerminalRun(source, deps(mock(state)));
453	
454	    if (state.rpcBodies.length !== 2) throw new Error("both ingests must still check the transaction in SQL");
455	    if (first.alreadyIngested !== false || second.alreadyIngested !== true) {
456	      throw new Error("the second ingest must be marked already_ingested");
457	    }
458	    if (second.counts.items !== 0 || second.counts.mentions !== 0 || second.counts.commitments !== 0) {
459	      throw new Error("a re-ingest must not report new rows");
460	    }
461	    if (state.events.length !== 1) {
462	      throw new Error("a re-ingest must not append a second ingested timeline row");
463	    }
464	  });
465	
466	  testFn("rejects an unparseable source before any write", async () => {
467	    let called = false;
468	    await ingestTerminalRun({
469	      callRunId: "",
470	      userId,
471	      raw: { status: "completed" },
472	      transcriptTurns: [],
473	      structuredResult: null,
474	    }, deps(() => {
475	      called = true;
476	      throw new Error("fetch must not run for an unparseable source");
477	    })).then(() => {
478	      throw new Error("a blank run id was accepted");
479	    }, (error) => {
480	      if (!(error instanceof Error) || !error.message.includes("call run id")) throw error;
481	    });
482	    if (called) throw new Error("an unparseable source reached the database");
483	  });
484	}
