1	/** Strict parser for the CALL-E result_schema in docs/calle-call.md. */
2	
3	export type Mood = "ok" | "low" | "stressed" | "energised" | "unknown";
4	export type SlotChangeRequested = "yes" | "no" | "unknown";
5	
6	export interface CapturedItemResult {
7	  text: string;
8	  evidence_offset_seconds: number;
9	}
10	
11	export interface RetiredItemResult {
12	  item_id: string;
13	  evidence_offset_seconds: number;
14	}
15	
16	export interface CommitmentResult {
17	  item_id: string;
18	  due?: string;
19	  evidence_offset_seconds: number;
20	}
21	
22	export interface StructuredCallResult {
23	  captured_items: CapturedItemResult[];
24	  retired_items: RetiredItemResult[];
25	  commitments?: CommitmentResult[];
26	  slot_change_requested?: SlotChangeRequested;
27	  slot_change_time?: string;
28	  mood?: Mood;
29	}
30	
31	export interface ParsedStructuredResult {
32	  result: StructuredCallResult | null;
33	  reason: string | null;
34	}
35	
36	const moods = new Set<Mood>(["ok", "low", "stressed", "energised", "unknown"]);
37	const slotChangeRequests = new Set<SlotChangeRequested>(["yes", "no", "unknown"]);
38	
39	function failure(reason: string): ParsedStructuredResult {
40	  return { result: null, reason };
41	}
42	
43	function object(value: unknown, path: string): Record<string, unknown> | string {
44	  if (value === null || Array.isArray(value) || typeof value !== "object") {
45	    return `${path} must be an object`;
46	  }
47	
48	  return value as Record<string, unknown>;
49	}
50	
51	function exactKeys(
52	  value: Record<string, unknown>,
53	  path: string,
54	  allowed: readonly string[],
55	  required: readonly string[],
56	): string | null {
57	  for (const key of required) {
58	    if (!(key in value)) return `${path}.${key} is required`;
59	  }
60	
61	  for (const key of Object.keys(value)) {
62	    if (!allowed.includes(key)) return `${path}.${key} is not allowed`;
63	  }
64	
65	  return null;
66	}
67	
68	function evidenceOffset(value: unknown, path: string): number | string {
69	  if (typeof value !== "number" || !Number.isInteger(value)) {
70	    return `${path} must be an integer`;
71	  }
72	
73	  return value;
74	}
75	
76	function string(value: unknown, path: string): string | string[] {
77	  return typeof value === "string" ? value : [`${path} must be a string`];
78	}
79	
80	function parseCapturedItem(value: unknown, path: string): CapturedItemResult | string {
81	  const candidate = object(value, path);
82	  if (typeof candidate === "string") return candidate;
83	
84	  const keyError = exactKeys(candidate, path, ["text", "evidence_offset_seconds"], [
85	    "text",
86	    "evidence_offset_seconds",
87	  ]);
88	  if (keyError) return keyError;
89	
90	  const text = string(candidate.text, `${path}.text`);
91	  if (Array.isArray(text)) return text[0];
92	  const offset = evidenceOffset(candidate.evidence_offset_seconds, `${path}.evidence_offset_seconds`);
93	  if (typeof offset === "string") return offset;
94	
95	  return { text, evidence_offset_seconds: offset };
96	}
97	
98	function parseRetiredItem(value: unknown, path: string): RetiredItemResult | string {
99	  const candidate = object(value, path);
100	  if (typeof candidate === "string") return candidate;
101	
102	  const keyError = exactKeys(candidate, path, ["item_id", "evidence_offset_seconds"], [
103	    "item_id",
104	    "evidence_offset_seconds",
105	  ]);
106	  if (keyError) return keyError;
107	
108	  const itemId = string(candidate.item_id, `${path}.item_id`);
109	  if (Array.isArray(itemId)) return itemId[0];
110	  const offset = evidenceOffset(candidate.evidence_offset_seconds, `${path}.evidence_offset_seconds`);
111	  if (typeof offset === "string") return offset;
112	
113	  return { item_id: itemId, evidence_offset_seconds: offset };
114	}
115	
116	function parseCommitment(value: unknown, path: string): CommitmentResult | string {
117	  const candidate = object(value, path);
118	  if (typeof candidate === "string") return candidate;
119	
120	  const keyError = exactKeys(candidate, path, ["item_id", "due", "evidence_offset_seconds"], [
121	    "item_id",
122	    "evidence_offset_seconds",
123	  ]);
124	  if (keyError) return keyError;
125	
126	  const itemId = string(candidate.item_id, `${path}.item_id`);
127	  if (Array.isArray(itemId)) return itemId[0];
128	  const offset = evidenceOffset(candidate.evidence_offset_seconds, `${path}.evidence_offset_seconds`);
129	  if (typeof offset === "string") return offset;
130	
131	  if ("due" in candidate) {
132	    const due = string(candidate.due, `${path}.due`);
133	    if (Array.isArray(due)) return due[0];
134	    return { item_id: itemId, due, evidence_offset_seconds: offset };
135	  }
136	
137	  return { item_id: itemId, evidence_offset_seconds: offset };
138	}
139	
140	function parseArray<T>(
141	  value: unknown,
142	  path: string,
143	  parser: (value: unknown, path: string) => T | string,
144	): T[] | string {
145	  if (!Array.isArray(value)) return `${path} must be an array`;
146	
147	  const parsed: T[] = [];
148	  for (const [index, item] of value.entries()) {
149	    const parsedItem = parser(item, `${path}[${index}]`);
150	    if (typeof parsedItem === "string") return parsedItem;
151	    parsed.push(parsedItem);
152	  }
153	
154	  return parsed;
155	}
156	
157	/**
158	 * Returns the complete validated object, or null with a durable failure reason.
159	 * Callers must persist only a non-null result.
160	 */
161	export function parseStructuredResult(value: unknown): ParsedStructuredResult {
162	  const candidate = object(value, "structured_result");
163	  if (typeof candidate === "string") return failure(candidate);
164	
165	  const keyError = exactKeys(
166	    candidate,
167	    "structured_result",
168	    [
169	      "captured_items",
170	      "retired_items",
171	      "commitments",
172	      "slot_change_requested",
173	      "slot_change_time",
174	      "mood",
175	    ],
176	    ["captured_items", "retired_items"],
177	  );
178	  if (keyError) return failure(keyError);
179	
180	  const capturedItems = parseArray(candidate.captured_items, "structured_result.captured_items", parseCapturedItem);
181	  if (typeof capturedItems === "string") return failure(capturedItems);
182	
183	  const retiredItems = parseArray(candidate.retired_items, "structured_result.retired_items", parseRetiredItem);
184	  if (typeof retiredItems === "string") return failure(retiredItems);
185	
186	  const result: StructuredCallResult = {
187	    captured_items: capturedItems,
188	    retired_items: retiredItems,
189	  };
190	
191	  if ("commitments" in candidate) {
192	    const commitments = parseArray(candidate.commitments, "structured_result.commitments", parseCommitment);
193	    if (typeof commitments === "string") return failure(commitments);
194	    result.commitments = commitments;
195	  }
196	
197	  if ("slot_change_requested" in candidate) {
198	    const slotChangeRequested = candidate.slot_change_requested;
199	    if (typeof slotChangeRequested !== "string" || !slotChangeRequests.has(slotChangeRequested as SlotChangeRequested)) {
200	      return failure("structured_result.slot_change_requested must be yes, no, or unknown");
201	    }
202	    result.slot_change_requested = slotChangeRequested as SlotChangeRequested;
203	  }
204	
205	  if ("slot_change_time" in candidate) {
206	    const slotChangeTime = string(candidate.slot_change_time, "structured_result.slot_change_time");
207	    if (Array.isArray(slotChangeTime)) return failure(slotChangeTime[0]);
208	    result.slot_change_time = slotChangeTime;
209	  }
210	
211	  if ("mood" in candidate) {
212	    const mood = candidate.mood;
213	    if (typeof mood !== "string" || !moods.has(mood as Mood)) {
214	      return failure("structured_result.mood has an invalid value");
215	    }
216	    result.mood = mood as Mood;
217	  }
218	
219	  return { result, reason: null };
220	}
