// Throwaway live drive of ingestTerminalRun against the shared scratch stack.
// Creates only terminal runs for one throwaway user, then deletes everything.
import { ingestTerminalRun, type IngestDeps } from "/home/nryn/work/orma/supabase/functions/_shared/ingest.ts";
import { loadCallFixtures } from "/home/nryn/work/orma/supabase/functions/_shared/fixtures.ts";

const tag = crypto.randomUUID().slice(0, 8);
const user = `e27e0000-0000-4000-8000-0000${tag}`;
const seed = `e27e0001-0000-4000-8000-0000${tag}`;
const run = (n: number) => `e27e00a${n}-0000-4000-8000-0000${tag}`;
const missingRun = `e27e00ff-0000-4000-8000-0000${tag}`;

function sql(query: string): string {
  const out = new Deno.Command("docker", {
    args: ["exec", "-i", "supabase_db_stack", "psql", "-U", "postgres", "-d", "postgres", "-At", "-v", "ON_ERROR_STOP=1", "-c", query],
  }).outputSync();
  if (!out.success) throw new Error(new TextDecoder().decode(out.stderr));
  return new TextDecoder().decode(out.stdout).trim();
}

const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const deps = (f: typeof fetch = fetch): IngestDeps => ({ apiUrl: Deno.env.get("ORMA_API_URL")!, serviceRoleKey: key, fetch: f });
const { completed } = await loadCallFixtures();
const turns = completed.recipients[0].attempts[0].transcript_turns;

sql(`insert into auth.users (id, aud, role, email) values ('${user}','authenticated','authenticated','t27-remed-${tag}@example.test');
insert into public.profiles (id, display_name) values ('${user}','T2.7 remediation ${tag}');
insert into public.items (id, user_id, text, source) values ('${seed}','${user}','renew the passport','seed');
insert into public.call_runs (id, user_id, local_date, part_of_day, scheduled_for, idempotency_key, state)
select ('e27e00a' || n || '-0000-4000-8000-0000${tag}')::uuid, '${user}', current_date, 'morning', now(), 't27-remed-${tag}-' || n, 'completed'
from generate_series(1,4) n;`);

try {
  // R1: the committed fixture, unmodified.
  const r1 = await ingestTerminalRun({ callRunId: run(1), userId: user, raw: completed, transcriptTurns: turns, structuredResult: completed.structured_result }, deps());
  console.log("R1 returned", JSON.stringify(r1));

  // R2: a free-text due on an owned item.
  const r2 = await ingestTerminalRun({ callRunId: run(2), userId: user, raw: { ...completed, id: "call_r2" }, transcriptTurns: turns,
    structuredResult: { captured_items: [], retired_items: [], commitments: [{ item_id: seed, due: "next Tuesday after work", evidence_offset_seconds: 80 }], mood: "ok" } }, deps());
  console.log("R2 returned", JSON.stringify(r2));

  // R3: a well-formed item id this user does not own.
  const r3 = await ingestTerminalRun({ callRunId: run(3), userId: user, raw: { ...completed, id: "call_r3" }, transcriptTurns: turns,
    structuredResult: { captured_items: [], retired_items: [{ item_id: crypto.randomUUID(), evidence_offset_seconds: 62 }] } }, deps());
  console.log("R3 returned", JSON.stringify(r3));

  // R4: the call_events POST fails once, after the RPC committed.
  let failed = 0;
  const flaky: typeof fetch = (input, init) => {
    const url = new Request(input, init).url;
    if (url.endsWith("/rest/v1/call_events") && failed++ === 0) return Promise.resolve(new Response("{}", { status: 503 }));
    return fetch(input, init);
  };
  const r4source = { callRunId: run(4), userId: user, raw: { ...completed, id: "call_r4" }, transcriptTurns: turns, structuredResult: completed.structured_result };
  await ingestTerminalRun(r4source, deps(flaky)).then(() => console.log("R4 first UNEXPECTEDLY resolved"), (e) => console.log("R4 first threw:", e.message));
  console.log("R4 after failure, ingested events:", sql(`select count(*) from public.call_events where call_run_id='${run(4)}' and kind='ingested'`));
  const r4b = await ingestTerminalRun(r4source, deps(flaky));
  const r4c = await ingestTerminalRun(r4source, deps(flaky));
  console.log("R4 retries returned", JSON.stringify(r4b.alreadyIngested), JSON.stringify(r4c.alreadyIngested));

  // R5: a run that does not exist.
  await ingestTerminalRun({ callRunId: missingRun, userId: user, raw: { status: "completed" }, transcriptTurns: [], structuredResult: null }, deps())
    .then(() => console.log("R5 UNEXPECTEDLY resolved"), (e) => console.log("R5 threw:", e.message));

  console.log("--- SQL pins ---");
  console.log(sql(`select r.id_suffix, cr.state, cr.disposition, coalesce(cr.mood,'null'),
      (select count(*) from public.transcripts t where t.call_run_id = cr.id) as transcripts,
      (select valid::text || ' ' || coalesce(error,'') from public.results x where x.call_run_id = cr.id) as result,
      (select count(*) from public.item_mentions m where m.call_run_id = cr.id) as mentions,
      (select string_agg(offset_seconds::text, ',' order by offset_seconds) from public.item_mentions m where m.call_run_id = cr.id) as offsets,
      (select count(*) from public.commitments c where c.call_run_id = cr.id) as commitments,
      (select count(*) from public.call_events e where e.call_run_id = cr.id and e.kind = 'ingested') as ingested_events,
      (select string_agg(e.detail::text, ' ; ') from public.call_events e where e.call_run_id = cr.id and e.kind = 'ingested') as detail
    from public.call_runs cr cross join lateral (select 'R' || substr(cr.id::text, 8, 1) as id_suffix) r
    where cr.user_id = '${user}' order by 1`));
  console.log("items for user:", sql(`select string_agg(source || ':' || status || ':' || text, ' | ' order by source, text) from public.items where user_id = '${user}'`));
} finally {
  sql(`delete from auth.users where id = '${user}'`);
  console.log("--- cleanup counts ---");
  console.log(sql(`select (select count(*) from auth.users where id='${user}') || ' ' ||
    (select count(*) from public.profiles where id='${user}') || ' ' ||
    (select count(*) from public.items where user_id='${user}') || ' ' ||
    (select count(*) from public.call_runs where user_id='${user}' or id::text like 'e27e00%${tag}') || ' ' ||
    (select count(*) from public.transcripts where call_run_id::text like 'e27e00%${tag}') || ' ' ||
    (select count(*) from public.results where call_run_id::text like 'e27e00%${tag}') || ' ' ||
    (select count(*) from public.call_events where call_run_id::text like 'e27e00%${tag}') || ' ' ||
    (select count(*) from public.item_mentions where item_id::text like 'e27e0001%${tag}' or call_run_id::text like 'e27e00%${tag}') || ' ' ||
    (select count(*) from public.commitments where user_id='${user}')`));
}

